function timelineV2(v){if(v.some(e=>e.id==="tBorn"))return v;const sh=v.find(e=>e.type==="shape");if(!sh)return v;
  sh.h=3600;const top=sh.y+330,step=Math.round((sh.h-330-220)/(TL2.length-1));
  const oldWins={};v.filter(e=>e.type==="window"&&/^win-/.test(e.id)).forEach(w=>oldWins[w.id]=w);
  for(let i=v.length-1;i>=0;i--){const e=v[i];if((e.type==="milestone"&&e.dot)||(e.type==="window"&&/^win-/.test(e.id)))v.splice(i,1)}
  const fi=v.findIndex(e=>e.type==="footer");const add=[];
  TL2.forEach((s,i)=>{const y=top+i*step,left=i%2===1,dx=shapeMidX(sh,y);
    let tx=left?120:960;if(dx>tx-30&&dx<tx+390)tx=left?960:120; // keep the dot clear of the text
    if(s.win){const w=oldWins[s.win]||{id:s.win,type:"window",name:"Photo",w:400,h:220,rad:110,src:null,caption:"Photo",r:0};w.w=400;w.x=tx===120?860:180;w.y=y-110;
      if(dx>w.x-30&&dx<w.x+w.w+30){w.w=340;w.x=tx===120?Math.min(dx+60,1420-340):Math.max(dx-400,20)}add.push(w)}
    add.push({id:s.id,type:"milestone",name:s.title,x:tx,y:y-46,w:360,year:"",swap:true,when:s.when,title:s.title,body:[s.body],dot:[dx,y]})});
  v.splice(fi<0?v.length:fi,0,...add);
  // spread the edge blobs over the longer road
  const bl=v.filter(e=>e.type==="blob"&&e.id!=="p2blob"&&e.y>sh.y-200).sort((a,b)=>a.y-b.y);
  bl.forEach((b,i)=>b.y=Math.round(top-60+i*(sh.h-400)/Math.max(1,bl.length-1)));
  v.filter(e=>e.type==="footer").forEach(f=>f.y=PAGES.p2.H-110);return v}
