// [label, size, shape, style] — shapes and overlaps after Lia's references (puzzle pills, soft glow rims, multiply overlaps)
// [label, size, sheet shape no., gradient] — bigger = more important
const TOPICS=[["Transport",300,1,"g:dawn"],["Urban planning",285,12,"g:lilac"],["AI",250,10,"g:lagoon"],["GIS & spatial analysis",230,16,"g:haze"],
  ["Sustainability",215,23,"g:meadow"],["Equity",190,2,"g:dawn"],["Urban design",180,7,"g:lilac"],["Traffic modelling",168,14,"g:lagoon"],
  ["Data science",150,3,"g:haze"],["Smart cities",140,26,"g:dawn"],["Climate resilience",130,19,"g:lagoon"],["Walkability",115,9,"g:lilac"],["TOD",105,13,"g:haze"]];
const bubR=(d,shape,aspect)=>shape==="pill"?d*aspect/2:shape==="clover"?d*0.62:d/2;
const TOP_Y=1860; // topics section starts here (after hero 0–900 and intro 900–1500)
function topicBubbles(){
  const out=[], cx=720, cy=0;
  TOPICS.forEach(([label,d0,no,fill],i)=>{
    const d=Math.round(d0*1.45),r=d/2*1.04;let x=cx,y=cy;
    for(let t=0;t<8000;t++){const a=t*0.31,rr=t*1.6;x=cx+Math.cos(a)*rr*1.25;y=cy+Math.sin(a)*rr*0.85;
      if(out.every(o=>Math.hypot(o.x-x,o.y-y)>(o.d/2+d/2)*1.1))break}
    const sh=sheetShape(no);
    out.push({id:"bub-"+i,type:"bubble",name:"Topic · "+label,label,x,y,d,shape:"harm",sheet:no,seed:sh.seed,ks:sh.ks,amp:sh.amp,hr:sh.rot,style:"glass",fill,float:true});
  });
  // stretch sideways so the cluster touches the left and right page edges
  const L=Math.min(...out.map(o=>o.x-o.d/2)),R=Math.max(...out.map(o=>o.x+o.d/2)),Tp=Math.min(...out.map(o=>o.y-o.d/2));
  out.forEach(o=>{o.x=Math.round(o.d/2+(o.x-o.d/2-L)*(1440-o.d)/((R-L)-o.d||1));o.y=Math.round(o.y-Tp+TOP_Y+170)});
  out.forEach(o=>{const l=o.x-o.d/2,rr=o.x+o.d/2;if(l>0&&l<40)o.x-=l;if(rr<1440&&rr>1400)o.x+=1440-rr});
  return[
    {id:"topicsLabel",type:"text",name:"Topics label",x:120,y:TOP_Y,text:"WHAT I FOLLOW",size:14,weight:500,font:"ui",fill:"#8C8B83",anchor:"start",r:0},
    {id:"topicsTitle",type:"text",name:"Topics title",x:120,y:TOP_Y+70,text:"Topics",size:72,weight:400,font:"display",fill:INK,anchor:"start",r:0},
    ...out]}
