function thumb(k){
  const s=`<svg viewBox="-110 -60 220 120" xmlns="${NS}">`;
  if(k.startsWith("blob")||k==="drop"){const e={shape:k==="blob-soft"?"soft":k==="drop"?"drop":"arms",seed:k==="drop"?415:k==="blob-soft"?77:20261010,lobes:6};
    return s+`<path d="${blobPath(e)}" transform="scale(${k==="drop"?0.42:0.55})" fill="${Y}"/></svg>`}
  if(k==="band")return s+`<path d="M-20,-60 C-80,-20 60,10 -10,60" stroke="${Y}" stroke-width="26" fill="none" stroke-linecap="round"/></svg>`;
  if(k==="milestone")return s+`<circle cx="-70" cy="-10" r="7" fill="#fff" stroke="currentColor" stroke-width="3"/><path d="M-70,-10 H-40 V-30 H-20" stroke="currentColor" stroke-width="2" fill="none"/><text x="-12" y="-18" font-family="IBM Plex Sans,sans-serif" font-size="30" fill="currentColor">2024</text><rect x="-12" y="0" width="90" height="6" fill="currentColor" opacity=".35"/><rect x="-12" y="14" width="70" height="6" fill="currentColor" opacity=".35"/></svg>`;
  if(k==="window")return s+`<rect x="-70" y="-36" width="140" height="72" rx="36" fill="#E9E8E2" stroke="currentColor" stroke-width="2"/></svg>`;
  if(k==="bubble")return s+`<circle cx="-30" cy="0" r="40" fill="${Y}"/><circle cx="40" cy="-14" r="26" fill="currentColor"/><circle cx="36" cy="34" r="16" fill="none" stroke="currentColor" stroke-width="2"/></svg>`;
  if(k==="form")return s+`<g fill="currentColor"><rect x="-70" y="-30" width="140" height="2"/><rect x="-70" y="0" width="140" height="2"/><rect x="-70" y="30" width="140" height="2"/></g><circle cx="60" cy="48" r="9" fill="#9FBDBF"/></svg>`;
  if(k==="contours")return s+`<g fill="none" stroke="currentColor" stroke-width="2"><ellipse rx="30" ry="18"/><ellipse rx="55" ry="32"/><ellipse rx="80" ry="46"/></g></svg>`;
  if(k==="poster")return s+`<rect x="-80" y="-50" width="160" height="100" fill="#8FAFAE"/><path d="M-80,-50 H30 C10,-20 40,10 20,50 H-80Z" fill="#B98A7A"/><path d="M-60,-50 L-30,0 L-70,40 M-30,0 L10,10 M-10,-50 L-30,0" stroke="#F4EFE8" stroke-width="2" fill="none"/></svg>`;
  if(k==="map")return s+`<rect x="-80" y="-50" width="160" height="100" rx="10" fill="none" stroke="currentColor" stroke-width="2"/><path d="M-60,-40 L-10,-45 L10,-10 L-20,20 L-55,10Z" fill="${Y}" stroke="currentColor" stroke-width="2"/><path d="M10,-10 L45,-30 L60,10 L20,35 L-20,20Z" fill="none" stroke="currentColor" stroke-width="2"/></svg>`;
  if(k==="title")return s+`<text x="-90" y="-6" font-family="Bodoni Moda,serif" font-size="40" fill="currentColor">AB</text><text x="-90" y="34" font-family="Bodoni Moda,serif" font-size="40" fill="#C9C8C0">CD</text></svg>`;
  if(k==="text")return s+`<text x="0" y="12" text-anchor="middle" font-family="Bodoni Moda,serif" font-weight="700" font-size="34" fill="currentColor">Aa</text></svg>`;
  if(k==="num")return s+`<text x="0" y="16" text-anchor="middle" font-family="IBM Plex Sans,sans-serif" font-size="48" fill="currentColor">01</text></svg>`;
  if(k==="meta")return s+`<g font-family="IBM Plex Sans,sans-serif" text-anchor="middle"><text y="-22" font-size="16" fill="#8C8B83">Date</text><text y="0" font-size="20" fill="currentColor">2026</text><text y="30" font-size="16" fill="#8C8B83">Type</text></g></svg>`;
  if(k==="line")return s+`<rect x="-40" y="-4" width="80" height="8" fill="currentColor"/></svg>`;
  if(k==="button")return s+`<circle r="36" fill="currentColor"/><path d="M-10,-4 L0,6 L10,-4" stroke="${Y}" stroke-width="4" fill="none" stroke-linecap="round"/></svg>`;
  return s+`<rect x="-34" y="-34" width="68" height="68" rx="6" fill="none" stroke="currentColor" stroke-dasharray="5 4" stroke-width="2"/><path d="M0,-14 V14 M-14,0 H14" stroke="currentColor" stroke-width="3"/></svg>`;
}
