  let h=`<section><p class="h">检查器 Inspector · ${e.type}</p>`+field("Name",`<input type="text" id="f-name" data-k="name" value="${esc(e.name||"")}">`);
  if(e.type!=="band")h+=`<div class="row2">${field("X",num("x",e.x))}${field("Y",num("y",e.y))}</div>`;
  const k=sizeKey(e);h+=field({w:e.type==="band"?"Thickness":"Width",size:"Font size",d:"Diameter",rings:"Rings"}[k],num(k,e[k]));
