    h+=field("Morph",`<input type="checkbox" id="f-morph" data-k="morph" ${e.morph?"checked":""}> <span class="hint">in preview</span>`);
    h+=field("Follow cursor",`<input type="checkbox" id="f-follow" data-k="follow" ${e.follow?"checked":""}> <span class="hint">in preview</span>`);
